def prt_results(self, goea_results):
        """Print GOEA results to the screen or to a file."""
        if self.outfile:
            with open(self.outfile, 'w') as fout:
                self.prt_results_to_file(goea_results, fout)
        else:
            self.prt_results_to_screen(goea_results)

